// B"H
const { compileSourceFilesToMode2 } = require('./SourceAppCompiler.js');
const { runMode2App, decodeMode2App, MAGIC } = require('./Mode2AppBinary.js');
const { encodeMode2JsBinary, runMode2JsBinary, decodeMode2JsBinary, MODE2_JS_MAGIC } = require('./Mode2JsBinary.js');

function normalizeFiles(files = {}) {
  const out = {};
  for (const [key, value] of Object.entries(files || {})) {
    const clean = String(key || '').replace(/\\/g, '/').replace(/^\.\//, '');
    out[clean] = String(value == null ? '' : value);
    if (!clean.startsWith('/')) out['/' + clean] = out[clean];
  }
  return out;
}

function asBuffer(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value instanceof Uint8Array) return Buffer.from(value);
  if (typeof value === 'string') return Buffer.from(value, 'base64');
  throw new Error('Expected md2 bytecode Buffer, Uint8Array, or base64 string.');
}

async function compileMd2App({ files = {}, entry = 'index.html' } = {}) {
  const normalized = normalizeFiles(files);
  const cleanEntry = String(entry || 'index.html').replace(/^\.\//, '');
  const bytecode = await compileSourceFilesToMode2({ files: normalized, entry: cleanEntry.startsWith('/') ? cleanEntry : '/' + cleanEntry });
  return { ok: true, kind: 'md2-app', magic: MAGIC, entry: cleanEntry, bytecode, bytecode64: Buffer.from(bytecode).toString('base64') };
}

function runMd2App(bytecode, options = {}) {
  const buffer = asBuffer(bytecode);
  const result = runMode2App(buffer, options);
  return { ok: result && result.ok !== false, kind: 'md2-app', magic: MAGIC, result };
}

async function compileAndRunMd2App(options = {}) {
  const compiled = await compileMd2App(options);
  return { ...compiled, run: runMd2App(compiled.bytecode, options.runOptions || options).result };
}

async function compileMd2Js(source = '', options = {}) {
  const bytecode = await encodeMode2JsBinary(String(source || ''), options);
  return { ok: true, kind: 'md2-js', magic: MODE2_JS_MAGIC, bytecode, bytecode64: Buffer.from(bytecode).toString('base64') };
}

function runMd2Js(bytecode, options = {}) {
  const buffer = asBuffer(bytecode);
  const result = runMode2JsBinary(buffer, options);
  return { ok: true, kind: 'md2-js', magic: MODE2_JS_MAGIC, result };
}

async function compileAndRunMd2Js(source = '', options = {}) {
  const compiled = await compileMd2Js(source, options);
  return { ...compiled, run: runMd2Js(compiled.bytecode, options).result };
}

function inspectMd2(bytecode) {
  const buffer = asBuffer(bytecode);
  const magic = buffer.slice(0, 4).toString('ascii');
  if (magic === MAGIC) return { ok: true, kind: 'md2-app', decoded: decodeMode2App(buffer) };
  if (magic === MODE2_JS_MAGIC) return { ok: true, kind: 'md2-js', decoded: decodeMode2JsBinary(buffer) };
  return { ok: false, error: 'unknown_md2_magic', magic };
}

module.exports = {
  normalizeFiles,
  compileMd2App,
  runMd2App,
  compileAndRunMd2App,
  compileMd2Js,
  runMd2Js,
  compileAndRunMd2Js,
  inspectMd2
};
